{"code":"def transform(grid):
    out=[row[:] for row in grid]
    R=len(grid); C=len(grid[0])
    def one(r,c): return 0<=r<R and 0<=c<C and grid[r][c]==1
    for r in range(R):
      for c in range(C):
        # central blank of the characteristic arrangement
        cells=[(r-3,c),(r-2,c),(r,c-3),(r,c-2),(r,c+2),(r,c+3),(r+2,c),(r+3,c),(r+2,c-2),(r+3,c-2)]
        if all(one(a,b) for a,b in cells) and grid[r][c]==8:
          out[r][c]=4
    return out"}

